UPDATE plan_comment
SET
    content = #{content},
    updated_at = #{updatedAt},
    path = #{path}
WHERE no = #{no}

UPDATE plan_comment
SET child_count = child_count + 1
WHERE no = #{parentNo}

UPDATE plan_comment
SET child_count = GREATEST(child_count - 1, 0)
WHERE no = #{parentNo}
